# Solve exact per-cluster translations for each demo by matching input cluster cells to output cells of same color.
def components(g,bg):
    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]; res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                stack=[(i,j)]; comp=[]
                while stack:
                    a,b=stack.pop()
                    if seen[a][b]: continue
                    seen[a][b]=True; comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]!=bg and not seen[na][nb]:
                            stack.append((na,nb))
                res.append(comp)
    return res
def solve(demo):
    g=G[demo+' input']; o=G[demo+' output']
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    comps=components(g,bg)
    ocnt=Counter(x for r in o for x in r if x!=bg)
    # group output cells by color
    out_by={}
    for i,r in enumerate(o):
        for j,x in enumerate(r):
            if x!=bg: out_by.setdefault(x,set()).add((i,j))
    sol={}
    for comp in comps:
        c=g[comp[0][0]][comp[0][1]]
        pts=sorted(comp)
        # try all deltas mapping pts into out_by[c], requiring |pts|==|target| or target contains pts shifted
        t=out_by.get(c,[])
        best=None
        for dr in range(-H,H):
            for dc in range(-W,W):
                mapped={(a+dr,b+dc) for a,b in pts}
                # valid if mapped subset of target and within grid
                if all(0<=a<len(o) and 0<=b<len(o[0]) for a,b in mapped) and mapped<=set(t):
                    # prefer minimal movement; also require every output cell of color c covered eventually? check global cover later
                    score=abs(dr)+abs(dc)
                    if best is None or score<best[0]: best=(score,dr,dc,mapped)
        sol[c]=best
    return bg,sol,out_by
for d in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    bg,sol,outb=solve(d)
    print('=====',d,'bg',bg)
