                key=(abs(dr)+abs(dc),dr,dc)
                if best is None or key<best[0]:
                    best=(key,shc)
        if best is None:
            print('NO valid move for',col); continue
        key,shc=best
        for i,j in shc: out[i][j]=col
    return out

